%[text] # Motor Drive Unit - Simulation Case
%[text] ## Randomly generated input signals
%[text] Test that the model runs with reasonably random inputs. This is part of stress-test.
MotorDriveUnit_BasicThermal_params
target_subsystem = "MotorDriveUnit_BasicThermal_refsub";

stop_time = "400";

model_name = "HarnessModel_MotorDriveUnit";
load_system(model_name)
%[text] Test conditions
LoadInputs_MotorDriveUnit_Random
%[text] Initial conditions
initial.LoadInertia_AngularSpeed = simscape.Value(0, "rpm");
initial.MotorDriveUnit_RotorAngularSpeed = simscape.Value(0, "rpm");
initial.AmbientTemperature = simscape.Value(273.15 + 20, "K");
%[text] 
sim_in = Simulink.SimulationInput(model_name);
sim_in = setBlockParameter(sim_in, model_name + "/Motor Drive Unit", ReferencedSubsystem = "MotorDriveUnit_BasicThermal_refsub");
sim_in = setBlockParameter(sim_in, model_name + "/Inputs", ReferencedSubsystem = "Inputs_MotorDriveUnit_LookupTable_refsub");
sim_in = setModelParameter(sim_in, StopTime = stop_time);
applyToModel(sim_in)
%[text] Run simulation.
sim_out = sim(sim_in);
%[text] Visually inspect the result.
sim_data = extractTimetable(sim_out.logsout);

% Signal logging names in the model.
signal_names = [
  "Motor torque command"
  "Axle torque input"
  "Motor power rate"
  "Motor speed"
  "Motor temperature"
  "Battery power"
  "Battery current"
  "Battery voltage"
  ];

for idx = 1 : numel(signal_names) %[output:group:7f1d04ae]
  fig = bevutil1.SignalUtil.plotTimedData(TimedData = sim_data, SignalName = signal_names(idx)); %[output:745556bf] %[output:7dbfb28c] %[output:6d19233a] %[output:40bd3358] %[output:75c99119] %[output:719cd506] %[output:51e6500b] %[output:33413c04]
  fig.Position(4) = 200;  % height
end %[output:group:7f1d04ae]
